PCM_CODECS = {"pcm_s16le", "pcm_s24le", "pcm_f32le"}
LOSSY_CODECS = {"libmp3lame", "aac", "libopus", "libvorbis"}
CONTAINER_CODECS = {
    ".wav": PCM_CODECS,
    ".flac": {"flac"},
    ".mp3": {"libmp3lame"},
    ".m4a": {"aac"},
    ".opus": {"libopus"},
}
VALUE_OPTIONS = {"-ss", "-t", "-to", "-ar", "-ac", "-c:a", "-c:v", "-c", "-af",
                 "-vf", "-b:a", "-map", "-loglevel", "-f"}
FLAG_OPTIONS = {"-y", "-n", "-vn", "-an", "-shortest", "-nostats"}


def _container(output):
    dot = output.rfind(".")
    return output[dot:].lower() if dot != -1 else ""


def ffmpeg_command(source, output, *, sample_rate=None, channels=None, codec=None,
                   filters=(), copy=False, start=None, duration=None,
                   fast_seek=False, drop_video=False, overwrite=True):
    if copy and (filters or codec or sample_rate is not None or channels is not None):
        raise ValueError("stream copy is remux only: it cannot filter or re-encode")
    if codec is not None:
        allowed = CONTAINER_CODECS.get(_container(output))
        if allowed is not None and codec not in allowed:
            raise ValueError(
                f"container {_container(output)} cannot hold codec {codec!r}")

    argv = ["ffmpeg", "-y" if overwrite else "-n", "-loglevel", "error"]
    if start is not None and fast_seek:
        argv += ["-ss", str(start)]
    argv += ["-i", source]
    if start is not None and not fast_seek:
        argv += ["-ss", str(start)]
    if duration is not None:
        argv += ["-t", str(duration)]
    if drop_video:
        argv.append("-vn")
    if copy:
        argv += ["-c", "copy"]
    if filters:
        argv += ["-af", ",".join(filters)]
    if sample_rate is not None:
        argv += ["-ar", str(sample_rate)]
    if channels is not None:
        argv += ["-ac", str(channels)]
    if codec is not None:
        argv += ["-c:a", codec]
    argv.append(output)
    return argv


def explain(argv):
    rest = argv[1:]
    input_options = {}
    output_options = {}
    inputs = []
    files = []
    current = input_options
    index = 0
    while index < len(rest):
        token = rest[index]
        if token == "-i":
            inputs.append(rest[index + 1])
            index += 2
            current = output_options
            continue
        if token in FLAG_OPTIONS:
            current[token] = True
            index += 1
            continue
        if token.startswith("-"):
            current[token] = rest[index + 1] if index + 1 < len(rest) else None
            index += 2
            continue
        files.append(token)
        index += 1
    copying = output_options.get("-c") == "copy"
    transforms = {"-ar", "-ac", "-af", "-vf", "-c:a", "-c:v"}
    return {
        "inputs": inputs,
        "output": files[-1] if files else None,
        "input_options": input_options,
        "output_options": output_options,
        "reencodes": (not copying) and any(k in output_options for k in transforms),
    }
